CREATE TABLE IF NOT EXISTS knovv_identity (id INTEGER PRIMARY KEY CHECK(id=1), owner TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS devices (id TEXT PRIMARY KEY, signing_public TEXT NOT NULL, generation INTEGER NOT NULL, revoked INTEGER NOT NULL CHECK(revoked IN (0,1)), envelope TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS objects (id TEXT PRIMARY KEY, size INTEGER NOT NULL CHECK(size>=0), uploaded INTEGER NOT NULL DEFAULT 0 CHECK(uploaded IN (0,1)));
CREATE TABLE IF NOT EXISTS usage (id INTEGER PRIMARY KEY CHECK(id=1), bytes INTEGER NOT NULL);
INSERT OR IGNORE INTO usage(id,bytes) VALUES (1,0);
CREATE TRIGGER IF NOT EXISTS objects_usage AFTER INSERT ON objects BEGIN UPDATE usage SET bytes=bytes+NEW.size WHERE id=1; END;
CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY, head TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS revisions (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, doc TEXT NOT NULL, parent TEXT, object TEXT NOT NULL REFERENCES objects(id), device TEXT NOT NULL REFERENCES devices(id), envelope TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS revisions_document ON revisions(doc,seq);
CREATE TRIGGER IF NOT EXISTS revisions_head AFTER INSERT ON revisions BEGIN INSERT INTO documents(id,head) VALUES (NEW.doc,NEW.id) ON CONFLICT(id) DO UPDATE SET head=NEW.id; END;
CREATE TABLE IF NOT EXISTS publications (id INTEGER PRIMARY KEY CHECK(id=1), generation INTEGER NOT NULL, epoch INTEGER NOT NULL, vault TEXT NOT NULL, digest TEXT NOT NULL, envelope TEXT NOT NULL);
